def snapshot(base,motion=False):return {p.relative_to(base).as_posix():sha(p) for p in base.rglob('*') if p.is_file() and '__pycache__' not in p.parts and (p.name not in ('bundle-manifest.json','freeze-receipt.json') if motion else p not in (base/'bundle-manifest.json',base/'freeze-receipt.json'))}
